import { mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import { DATA_DIR } from '$app/env/private';

export const mediaDir = resolve(DATA_DIR, 'media');
export const uploadsDir = resolve(DATA_DIR, 'uploads');

export async function ensureStorage(): Promise<void> {
	await mkdir(mediaDir, { recursive: true });
	await mkdir(uploadsDir, { recursive: true });
}

/** Upload ids are UUIDs generated by the database, so the path cannot escape the uploads directory. */
export function uploadPath(id: string): string {
	return resolve(uploadsDir, `${id}.zip`);
}
